package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;
import io.knowledgebrain.contracts.planning.schedule.v1.ScheduleChangedPayloadV1;
import io.knowledgebrain.contracts.planning.task.v1.TaskChangedPayloadV1;
class PlanningActivityTest extends ActivityFixtures {
 @Test void pinnedScheduleOffsetsAreNotRecomputedFromCurrentZoneRules()throws Exception{var topic=ActivityEvent.TOPICS.get("SCHEDULE");var wire=wire("SCHEDULE",id());var e=ActivityEvent.decode(topic,wire);assertNull(e.roadmapId());assertEquals("2028-11-05T01:30:00",e.planning().startsLocal());assertEquals(e.planning().startsLocal(),e.planning().endsLocal());assertEquals("-04:00",e.planning().startsOffset());assertEquals("-05:00",e.planning().endsOffset());assertNull(e.startedAt());assertEquals(0,e.durationSeconds());assertTrue(e.targetPath().endsWith("/schedules/"+e.aggregateId()));var envelope=RoadmapEventEnvelopeV1.parseFrom(wire);var p=ScheduleChangedPayloadV1.parseFrom(envelope.getPayload());var changed=p.toBuilder().setTimeZone("UTC").build();assertEquals(e.planning().startsLocal(),ActivityEvent.decode(topic,envelope.toBuilder().setPayload(changed.toByteString()).build().toByteArray()).planning().startsLocal());for(var bad:List.of(p.toBuilder().setEndsAt(p.getStartsAt()),p.toBuilder().setStartsOffset("-05:00"),p.toBuilder().setTimeZone("+09:00"),p.toBuilder().setStartsLocal("2028-02-30T01:30:00"),p.toBuilder().setTaskId(UUID.randomUUID().toString()),p.toBuilder().setState("RETIRED"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(topic,envelope.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}}
 @Test void goalAndTaskStatusDatesAndLinksRemainIndependentOfLifecycle()throws Exception{for(String kind:List.of("GOAL","TASK")){var e=ActivityEvent.decode(ActivityEvent.TOPICS.get(kind),wire(kind,id()));assertEquals("ACTIVE",e.state());assertEquals("IN_PROGRESS",e.planning().status());assertEquals("2028-11-05",e.planning().date());assertEquals("Pinned planning description",e.detail());assertEquals("planning",ActivityEvent.group(kind));assertTrue(ActivityEvent.target(e));}var topic=ActivityEvent.TOPICS.get("TASK");var env=RoadmapEventEnvelopeV1.parseFrom(wire("TASK",id()));var p=TaskChangedPayloadV1.parseFrom(env.getPayload());var archived=p.toBuilder().setVersion(2).setState("RETIRED").setStatus("COMPLETED").setGoalId("").setDueDate("").build();var e=ActivityEvent.decode(topic,env.toBuilder().setEventType("TaskRetired").setPayload(archived.toByteString()).build().toByteArray());assertEquals("COMPLETED",e.planning().status());assertNull(e.planning().date());assertNull(e.planning().goalId());for(var bad:List.of(p.toBuilder().setDueDate("2028-02-30"),p.toBuilder().setStatus("OVERDUE"),p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setDescription("x".repeat(32769)),p.toBuilder().setUpdatedAt("2020-01-01T00:00:00Z"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(topic,env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}var wrong=new HashMap<>(headers(e));wrong.put("schema_group","learning");assertThrows(IllegalArgumentException.class,()->ActivityEvent.transport(topic,env.toByteArray(),env.getAggregateId(),wrong));}
 @Test void planningTypeCursorsCannotCrossFiltersOrSpaces(){var space=id();var params=ActivityQueryTest.params("kind","SCHEDULE","timezone","UTC");var q=ActivityQuery.parse(space,params);var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("SCHEDULE"),wire("SCHEDULE",space));params.put("before",new String[]{q.cursor(e)});assertEquals(e.eventId(),ActivityQuery.parse(space,params).event());assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),params));params.put("kind",new String[]{"TASK"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(space,params));}
}
